// ═══════════════════════════════════════════════════════════
// Configure your businesses here.
// Works for ANY institution: restaurants, clinics, banks,
// telecom, malls, government services, etc.
// ═══════════════════════════════════════════════════════════

const businesses = [
  {
    place_id: 'ChIJN1t_tDeuEmsRUsoyG83frY4',   // Replace with real place_id
    business_name: 'My Business'                  // Replace with real name
  },
  // Add more businesses below:
  // {
  //   place_id: 'ChIJ...',
  //   business_name: 'Another Business'
  // },
];

return businesses.map(b => ({ json: b }));

// Get business info from the Loop node input
const loopItems = $('Loop Over Businesses').all();
const business = loopItems[0]?.json || {};
const placeId = business.place_id || 'unknown';
const businessName = business.business_name || 'Unknown Business';

const reviews = $input.first()?.json?.reviews || [];

if (reviews.length === 0) {
  // No reviews or API error — skip silently
  return [];
}

// Transform each review to match DialectIQ POST /reviews schema:
// { business_name, place_id, text, rating, author_name }
return reviews
  .filter(r => {
    const text = r.text?.text || r.originalText?.text || '';
    return text.trim().length > 0;
  })
  .map(review => ({
    json: {
      business_name: businessName,
      place_id: placeId,
      text: review.text?.text || review.originalText?.text || '',
      rating: review.rating || 3,
      author_name: review.authorAttribution?.displayName || 'Anonymous'
    }
  }));

// Summarize results for logging
const items = $input.all();
const success = items.filter(i => i.json?.status === 'analyzed').length;
const failed = items.filter(i => i.json?.error || i.json?.status !== 'analyzed').length;

return [{
  json: {
    summary: `Processed ${items.length} reviews: ${success} analyzed, ${failed} failed`,
    total: items.length,
    success,
    failed,
    timestamp: new Date().toISOString()
  }
}];

// Validate incoming webhook payload matches DialectIQ schema
const body = $input.first().json?.body || $input.first().json || {};

const required = ['business_name', 'place_id', 'text', 'rating', 'author_name'];
const missing = required.filter(f => !body[f]);

if (missing.length > 0) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

// Clamp rating to 1-5
const rating = Math.max(1, Math.min(5, parseInt(body.rating) || 3));

return [{
  json: {
    business_name: String(body.business_name).slice(0, 255),
    place_id: String(body.place_id).slice(0, 255),
    text: String(body.text).slice(0, 5000),
    rating: rating,
    author_name: String(body.author_name).slice(0, 255)
  }
}];
